import glob
import json

merged = {}
for path in glob.glob("stores/*.json"):
    with open(path, encoding="utf-8") as f:
        data = json.load(f)
    for item, qty in data["库存"].items():
        merged[item] = merged.get(item, 0) + qty
for item in sorted(merged):
    print(f"{item} {merged[item]}")
